#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nType;  int nValue;  // Для типа 0  POINT pt;  int r;  double nValueM,nValueX;  double a,b;  RECT  mRectBrown;  COLORREF color;  COLORREF colorTrans;  //  } Queue_PumpSH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPumpSH(DefinePaint)  {  QueueP(Queue_PumpSH);  //  CShPump* sh=NULL;  if (p->nNumber!=-1)	sh = (CShPump*)PipeSh;  else  if (p->nSocketNumber!=-1)	sh=(CShPump*)q.m_pSocket->Sh(p->nSocketNumber);  //  if (sh==NULL)	  return 1;  //  //if ( !(IsTypeOK) ) return 1;  //  //CMyPen   pn( hDC, 0x80ff, 0 );  //pn.Rect( p->rc );  if ( p->nType == 1 && (IsTypeOk) )    {    if ( sh->VentDrain <= 0. ) return 1;    int Index = -1;	  switch( sh->eDrain )	    {      case CPumpData::DRAIN_LIQ :Index = 2;break;      case CPumpData::DRAIN_GAS :Index = 1;break;      case CPumpData::DRAIN_NO  :      default: return 1;	    };    static TCHAR* text[] =       {	    "Идет Х.З."    ,	    "Идет газ"     ,	    "Идет жидкость",      };    ::DrawText( hDC, text[Index], lstrlen(text[Index]), &p->mRect,      DT_CENTER | DT_VCENTER | DT_SINGLELINE );    }  else  if ( p->nType == 2 && (IsTypeOk) )    {    double dValue = sh->Pmanom;    dValue = max( dValue, p->nValueM );    dValue = min( dValue, p->nValueX );    //    CMyPen   pen( hDC, 0x808080, 2 );    //    ::MoveToEx( hDC, p->pt.x, p->pt.y, NULL );    double dAngle = M_PI*(dValue*p->a-p->b) / 180.;    int x = (int)( p->r*cos( dAngle ) );    int y = (int)( p->r*sin( dAngle ) );    ::LineTo  ( hDC, p->pt.x+x, p->pt.y+y );    }  else  if ( p->nType == 3 && (IsTypeOk) )    {    double dValue = 0;    switch ( p->nValue )      {      case 3:dValue = sh->VentDrain;break;// Дренаж насоса      case 5:dValue = sh->VentIN   ;break;// Регулирование входного вентиля      case 6:dValue = sh->VentOUT  ;break;// Регулирование выходного вентиля	    case 7:dValue = sh->VentIN_2   ;break;// Регулирование входного вентиля2      case 8:dValue = sh->VentOUT_2  ;break;// Регулирование выходного вентиля2      }    DrawValue( hDC, p, dValue, "%" );    }  else  if ( p->nType == 4 )    {    if ( ::IsMnemoStyle(MNEMO_EDIT) )    if ( !IsTypeOk )      {      TransparentRect( hDC, p->mRect, 0x80ff, 0xffffff );      }    }  else  if ( p->nType == 5 )    {    const char* name = q.m_pPipe->GetMnemoName( p->nNumber );    CMyFont font( hDC, NULL, 0x00 );    font.Draw( p->mRect, name );    }  else    if ( p->nType == 6 )    {		if ( IsTypeOk )		{				if (sh->Eq_State( CPumpData::Work ))				{					TransparentRect(hDC,p->mRect,p->color,p->colorTrans);					TransparentRect(hDC,p->mRectBrown,0x004080,p->colorTrans);				}		}		else			if	( ::GetMnemoStyle() & MNEMO_EDIT )			{				TransparentRect(hDC,p->mRect,0x80ff,p->colorTrans);				TransparentRect(hDC,p->mRectBrown,0x80ff,p->colorTrans);			}	}	else		if(p->nType==7)		{			const char* name = q.m_pPipe->GetModelName( p->nNumber );			    ::DrawText( hDC, name, lstrlen(name), &p->mRect,				DT_CENTER | DT_VCENTER | DT_SINGLELINE );		}  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPumpSH(DefineTegs)  {  //  AddQueueEx(Queue_PumpSH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPumpSH;  //  p->nValueM = 0.0;  p->nValueX = 2.0;  p->color=RGB(0,255,0);  p->colorTrans=0xcdcccc;  p->nSocketNumber=-1;  p->nNumber=-1;  //  STegObj obj[] =    {    { 'I', "type" , &p->nType },    { 'D', "min", &p->nValueM },    { 'D', "max", &p->nValueX },	{ 'R', "rectBrown"   , &p->mRectBrown  },	{ 'A', "color", &p->color  },	{ 'A', "colorTrans", &p->colorTrans  },    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSH( def, id_Pump, teg[0].value, p, p->nValue );  //  if ( p->nType == 2 )    {    int w = p->W();    int h = p->H();    p->pt.y = p->Cy();    p->pt.x = p->Cx();    p->r    = h/2;    //    double nAngleX =  47;    double nAngleM = -227;    //    p->a = double( nAngleX-nAngleM )/( p->nValueX-p->nValueM );    p->b =  (p->nValueM*p->a-nAngleM);    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~